def can_make_abc(s):
    if s == "abc":
        return "YES"

    # Check if swapping any two characters can result in "abc"
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] + s[j] == "abc":
                return "YES"

    return "NO"

