def determine_winner(n):
    if n % 3 == 0:
        return "First"
    for _ in range(10):
        if n % 3 == 0:
            return "First"
        if n % 3 == 1:
            n += 1
        elif n % 3 == 2:
            n -= 1
    return "Second"

