def sum_of_powers(nums):
    MOD = 10**9 + 7
    n = len(nums)
    total_power = 0

    for i in range(n):
        max_element = nums[i]
        min_element = nums[i]
        for j in range(i + 1, n):
            if nums[j] > max_element:
                max_element = nums[j]
            elif nums[j] < min_element:
                min_element = nums[j]
            total_power = (total_power + max_element ** 2 * min_element) % MOD

    return total_power

def is_valid_original(derived):
    n = len(derived)
    original = [0] * n
    original[n - 1] = derived[n - 1] ^ original[0]
    for i in range(n - 2, -1, -1):
        original[i] = derived[i] ^ original[i + 1]
        if original[i] != 0:
            return False
    return True

def min_length(s: str) -> int:
    stack = []
    for char in s:
        if stack and stack[-1] != char:
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

def make_palindrome(s: str) -> str:
    s = list(s)
    for i in range(len(s) // 2):
        if s[i] != s[len(s) - 1 - i]:
            s[i] = s[len(s) - 1 - i]
    return ''.join(s)

def countSpecialPermutations(nums):
    MOD = 10**9 + 7
    n = len(nums)
    memo = {}

    def dp(i, j):
        if i == n:
            return 1
        if (i, j) in memo:
            return memo[(i, j)]
        if i > j:
            return 0
        if i == j:
            return 1
        if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
            result = dp(i + 1, j) + dp(i + 1, j + 1)
        else:
            result = dp(i + 1, j)
        memo[(i, j)] = result
        return result

    return dp(0, 0) % MOD

def min_changes_to_semi_palindrome(s, k):
    n = len(s)

    # Function to calculate the cost of making a substring a semi-palindrome
    def cost(substring):
        length = len(substring)
        min_cost = float('inf')
        for d in range(1, length):
            if length % d == 0:
                cost = 0
                for i in range(d):
                    left = i
                    right = i + d - 1
                    while left < right:
                        if substring[left] != substring[right]:
                            cost += 1
                        left += d
                        right -= d
                min_cost = min(min_cost, cost)
        return min_cost

    # Initialize the dp array
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            for p in range(i):
                cost = cost(s[p:i])
                dp[i][j] = min(dp[i][j], dp[p][j-1] + cost)

    return dp[n][k]

def longestValidSubstring(word: str, forbidden: list[str]) -> int:
    forbidden_set = set(forbidden)
    max_length = 0
    left = 0
    for right in range(len(word)):
        while left <= right and word[left:right+1] in forbidden_set:
            left += 1
        max_length = max(max_length, right - left + 1)
    return max_length

