def getMaxFunctionValue(receiver, k):
    n = len(receiver)
    # Binary lifting table
    binary_lift = [[0] * n for _ in range(n)]
    # Initialize the binary lifting table
    for i in range(n):
        binary_lift[i][i] = receiver[i]
    # Fill the binary lifting table
    for j in range(1, n):
        for i in range(n):
            if binary_lift[i][j-1] != 0:
                binary_lift[i][j] = binary_lift[binary_lift[i][j-1]][j-1]
    # Function to calculate the sum of player IDs after k passes
    def calculate_sum(x, k):
        sum_ids = x
        for j in range(k):
            sum_ids += binary_lift[sum_ids][j]
        return sum_ids
    # Find the maximum value of f(x)
    max_value = 0
    for x in range(n):
        max_value = max(max_value, calculate_sum(x, k))
    return max_value

def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7
    dp = [0] * (r + 1)
    dp[0] = 1
    for num in nums:
        for i in range(num, r + 1):
            dp[i] = (dp[i] + dp[i - num]) % MOD
    return dp[l]

