def find_champion(grid):
    n = len(grid)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                return i
    return -1

def min_steps_to_group_balls(s: str) -> int:
    steps = 0
    i = 0
    while i < len(s):
        if s[i] == '1':
            steps += 1
            i += 1
        else:
            i += 1
    return steps

def canMakePalindrome(s, queries):
    n = len(s)
    half = n // 2

    # Count the frequency of each character in the string
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Check if the string can be rearranged to be a palindrome
    for char in freq:
        if freq[char] % 2 != 0:
            return False

    # Check each query
    answer = []
    for a, b, c, d in queries:
        # Create a copy of the frequency dictionary
        freq_copy = freq.copy()

        # Rearrange the characters within the specified substrings
        for i in range(a, b + 1):
            freq_copy[s[i]] -= 1
        for i in range(c, d + 1):
            freq_copy[s[i]] -= 1

        # Add the remaining characters to the frequency dictionary
        for i in range(a, b + 1):
            freq_copy[s[i]] += 1
        for i in range(c, d + 1):
            freq_copy[s[i]] += 1

        # Check if the frequency dictionary is a palindrome
        for i in range(half):
            if freq_copy[s[i]] != freq_copy[s[n - i - 1]]:
                answer.append(False)
                break
        else:
            answer.append(True)

    return answer

def min_operations_to_equal_strings(s1, s2, s3):
    if s1[0] != s2[0] or s2[0] != s3[0]:
        return -1

    # Find the longest common prefix
    common_prefix_length = 0
    for i in range(min(len(s1), len(s2), len(s3))):
        if s1[i] == s2[i] == s3[i]:
            common_prefix_length += 1
        else:
            break

    return common_prefix_length

def num_good_partitions(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * n
    dp[0] = 1
    last_occurrence = {}

    for i in range(1, n):
        dp[i] = dp[i-1]
        if nums[i] in last_occurrence:
            last_occurrence[nums[i]] = i
        else:
            last_occurrence[nums[i]] = i

        for j in range(i-1, -1, -1):
            if nums[j] == nums[i]:
                dp[i] = (dp[i] + dp[j]) % MOD

    return dp[n-1]

def lexicographically_smallest_array(nums, limit):
    n = len(nums)
    for i in range(n):
        if i == 0:
            continue
        if nums[i] > nums[i - 1]:
            nums[i] = nums[i - 1]
        elif nums[i] < nums[i - 1]:
            nums[i] = nums[i - 1]
        else:
            nums[i] = min(nums[i - 1], nums[i])
    return nums

