def longest_special_substring(s: str) -> int:
    from collections import defaultdict

    # Dictionary to store the count of each special substring
    special_substring_count = defaultdict(int)

    # Iterate through the string to find all special substrings
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substring = s[i:j]
            if len(substring) == 1:
                special_substring_count[substring] += 1

    # Find the longest special substring that occurs at least three times
    max_length = -1
    for substring, count in special_substring_count.items():
        if count >= 3:
            max_length = max(max_length, len(substring))

    return max_length

def last_non_repeated_string(s: str) -> str:
    char_list = []
    for char in s:
        if char not in char_list:
            char_list.append(char)
    return ''.join(char_list)

