def find_connected_components(N, M, sets):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for i, s in enumerate(sets):
        for j, elem in enumerate(s):
            if i != j and elem in s:
                graph[i].append(j)

    visited = set()
    components = []

    def bfs(start):
        queue = deque([start])
        component = []
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                component.append(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return component

    for i in range(N):
        if i not in visited:
            component = bfs(i)
            components.append(component)

    return components

def min_operations_to_obtain_both_1_and_M(N, M, sets):
    components = find_connected_components(N, M, sets)

    for component in components:
        if 1 in component and M in component:
            return len(component) - 1

    return -1

