def can_complete_moves(N, M, H, K, S, items):
    x, y = 0, 0
    health = H
    for move in S:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        health -= 1
        if health < 0:
            return "No"
        if (x, y) in items and health < K:
            health = K
    return "Yes"

