def min_time_to_transform(X, Y, Z, S):
    if S == S[::-1]:
        return 0

    # Calculate the time to append 'A' to the string if it starts with 'A'
    if S[0] == 'A':
        time_to_append_A = X + Y
    else:
        time_to_append_A = X

    # Calculate the time to append 'a' to the string if it starts with 'a'
    if S[0] == 'a':
        time_to_append_a = Y
    else:
        time_to_append_a = Y

    # Calculate the time to append 'A' to the string if it starts with 'A' and the next character is 'a'
    if S[0] == 'A' and S[1] == 'a':
        time_to_append_A_a = X + Y
    else:
        time_to_append_A_a = X

    # Calculate the time to append 'a' to the string if it starts with 'a' and the next character is 'A'
    if S[0] == 'a' and S[1] == 'A':
        time_to_append_a_A = Y
    else:
        time_to_append_a_A = Y

    # Calculate the time to append 'A' to the string if it starts with 'A' and the next character is 'a'
    if S[0] == 'A' and S[1] == 'a':
        time_to_append_A_a = X + Y
    else:
        time_to_append_A_a = X

    # Calculate the time to append 'a' to the string if it starts with 'a' and the next character is 'A'
    if S[0] == 'a' and S[1] == 'A':
        time_to_append_a_A = Y
    else:
        time_to_append_a_A = Y

    # Calculate the total time required to transform the initial string into the target string
    total_time = min(time_to_append_A, time_to_append_a, time_to_append_A_a, time_to_append_a_A, time_to_append_A_a, time_to_append_a_A)

    return total_time

