import math

def is_infected(N, D, points):
    infected = [False] * N
    infected[0] = True  # Person 1 is infected

    for i in range(1, N):
        for j in range(i + 1, N):
            distance = math.sqrt((points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2)
            if distance <= D:
                infected[j] = True

    return infected

def main():
    N, D = map(int, input().split())
    points = [tuple(map(int, input().split())) for _ in range(N)]
    infected = is_infected(N, D, points)
    for i in range(N):
        if infected[i]:
            print("Yes")
        else:
            print("No")

