def find_eaten_cookie(H, W, grid):
    # Initialize the top-left and bottom-right corners of the rectangle
    top_left = (0, 0)
    bottom_right = (H-1, W-1)

    # Find the top-left and bottom-right corners of the rectangle
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                top_left = (i, j)
            elif grid[i][j] == '.':
                bottom_right = (i, j)

    # Find the eaten cookie
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                return (i+1, j+1)  # Convert to 1-based index

