from collections import deque

def bfs(graph, start, end):
    queue = deque([start])
    visited = set([start])
    distance = 0
    while queue:
        node = queue.popleft()
        if node == end:
            return distance
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
                distance += 1
    return -1  # If no path is found

def find_guarded_vertices(N, M, K, edges, guards):
    graph = {i: [] for i in range(1, N + 1)}
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    guarded_vertices = set()
    for p, h in guards:
        for v in range(1, N + 1):
            if bfs(graph, p, v) <= h:
                guarded_vertices.add(v)
                break

    return sorted(guarded_vertices)

def main():
    import sys
    input = sys.stdin.read().split()

    N = int(input[0])
    M = int(input[1])
    K = int(input[2])

    edges = []
    for i in range(M):
