    guards = []
    for i in range(K):
        p = int(input[5 + 2 * i])
        h = int(input[6 + 2 * i])
        guards.append((p, h))

    guarded_vertices = find_guarded_vertices(N, M, K, edges, guards)
    print(len(guarded_vertices))
    print(" ".join(map(str, guarded_vertices)))

