    for i in range(M):
        a = int(input[3 + 2 * i])
        b = int(input[4 + 2 * i])
        graph[a].append((b, 1))
        graph[b].append((a, 1))

    distances_from_1 = dijkstra(graph, 1)
    distances_from_N1_N2 = dijkstra(graph, N1 + N2)

