def count_ways(N, T, M, incompatible_pairs):
    incompatible_pairs.sort(key=lambda x: x[0])
    dp = [[0] * (T + 1) for _ in range(N + 1)]
    dp[1][1] = 1

    for i in range(2, N + 1):
        for j in range(1, T + 1):
            dp[i][j] = dp[i-1][j]
            for k in range(1, i):
                if (incompatible_pairs[k-1][0] != i and incompatible_pairs[k-1][1] != j):
                    dp[i][j] += dp[i-1][j-1] * (i-1)

    return dp[N][T]

