def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    else:
        gcd, x, y = extended_gcd(b % a, a)
        return gcd, y - (b // a) * x, x

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Inverse does not exist")
    else:
        return x % m

def solve(N, A):
    dp = [[0] * 11 for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(11):
            dp[i][j] = dp[i-1][j]
            if j >= A[i-1]:
                dp[i][j] += dp[i-1][j-A[i-1]]
            dp[i][j] %= MOD

    total_outcomes = 1
    for a in A:
        total_outcomes = (total_outcomes * a) % MOD

    ways_to_get_10 = dp[N][10]
    inverse_total_outcomes = mod_inverse(total_outcomes, MOD)

    result = (ways_to_get_10 * inverse_total_outcomes) % MOD
    return result

