def count_holeless_squares(H, W, N, holed_squares):
    # Create a grid of size (H+1) x (W+1) to handle boundary conditions easily
    grid = [[0] * (W + 1) for _ in range(H + 1)]

    # Mark the holed squares in the grid
    for a, b in holed_squares:
        grid[a][b] = 1

    # Count the number of holeless squares
    holeless_count = 0

    # Iterate over each possible square size (n) from 1 to min(H, W)
    for n in range(1, min(H, W) + 1):
        # Iterate over each possible top-left corner (i, j) of the square
        for i in range(1, H - n + 2):
            for j in range(1, W - n + 2):
                # Check if the square region (i, j) to (i+n-1, j+n-1) is holeless
                is_holeless = True
                for k in range(n):
                    for l in range(n):
                        if grid[i + k][j + l] == 1:
                            is_holeless = False
                            break
                    if not is_holeless:
                        break
                if is_holeless:
                    holeless_count += 1

    return holeless_count

