import math

def calculate_distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def calculate_total_distance(checkpoints):
    total_distance = 0
    for i in range(1, len(checkpoints)):
        total_distance += calculate_distance(checkpoints[i-1][0], checkpoints[i-1][1], checkpoints[i][0], checkpoints[i][1])
    return total_distance

def calculate_penalty(checkpoints, C):
    penalty = 0
    for i in range(1, len(checkpoints)):
        if i > C:
            penalty += 2 ** (i - C - 1)
    return penalty

def find_minimum_s(N, checkpoints):
    min_s = float('inf')
    for C in range(1, N):
        penalty = calculate_penalty(checkpoints, C)
        total_distance = calculate_total_distance(checkpoints)
        s = total_distance + penalty
        if s < min_s:
            min_s = s
    return min_s

