def count_valid_permutations(grid):
    def is_valid(perm):
        for i in range(3):
            for j in range(3):
                if perm[i][j] == perm[i+1][j] and perm[i][j] != perm[i+2][j]:
                    return False
                if perm[i][j] == perm[i][j+1] and perm[i][j] != perm[i][j+2]:
                    return False
                if perm[i][j] == perm[i+1][j+1] and perm[i][j] != perm[i+2][j+2]:
                    return False
        return True

    def backtrack(perm, used):
        if len(perm) == 9:
            return 1
        count = 0
        for num in range(1, 10):
            if not used[num]:
                used[num] = True
                count += backtrack(perm + [num], used)
                used[num] = False
        return count

    used = [False] * 10
    return backtrack([], used)

