def calculate_coordinates(N, M, edges):
    from collections import defaultdict

    # Create a graph
    graph = defaultdict(list)
    for A, B, X, Y in edges:
        graph[A].append((B, X, Y))
        graph[B].append((A, -X, -Y))

    # Calculate coordinates
    coordinates = {}
    for person, neighbors in graph.items():
        if len(neighbors) == 1:
            coordinates[person] = (neighbors[0][0], neighbors[0][1])
        else:
            for neighbor, x, y in neighbors:
                if (x, y) not in coordinates:
                    coordinates[(x, y)] = (neighbor, x, y)

    # Check for undecidable coordinates
    for person, (x, y) in coordinates.items():
        if len(graph[person]) > 1:
            return "undecidable"

    return coordinates

