def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    P = int(input[2])

    C = [int(input[i+3]) for i in range(N)]
    A = [[int(input[i+4+j]) for j in range(K)] for i in range(N)]

    # Initialize DP table with infinity
    dp = [[float('inf')] * (P + 1) for _ in range(K + 1)]
    dp[0][0] = 0

    for i in range(N):
        for j in range(K):
            for k in range(P + 1):
                if dp[j][k] != float('inf'):
                    for l in range(K):
                        if l != j:
                            new_k = k + A[i][l]
                            if new_k >= P:
                                dp[j][new_k] = min(dp[j][new_k], dp[j][k] + C[i])

    # Find the minimum cost to achieve at least P in any parameter
    min_cost = float('inf')
    for j in range(K + 1):
        for k in range(P + 1):
            if dp[j][k] != float('inf'):
                min_cost = min(min_cost, dp[j][k])

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

