import heapq

def dijkstra(n, a, b, c, graph):
    dist = [float('inf')] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]
    while pq:
        dist_curr, u = heapq.heappop(pq)
        if dist_curr > dist[u]:
            continue
        for v in range(1, n + 1):
            if graph[u][v] != 0:
                dist_to_v = dist_curr + graph[u][v] * a
                if dist_to_v < dist[v]:
                    dist[v] = dist_to_v
                    heapq.heappush(pq, (dist_to_v, v))
    return dist

