    if len(S) != len(T):
        return "No"

    X = ['#'] * N

    for i in range(N):
        if X[i] == '#':
            continue

        j = i
        while j < N and X[j] == '#':
            j += 1

        if j == N:
            return "No"

        for k in range(M):
            if X[j + k] != T[k]:
                return "No"

        X[j:j + M] = T

        if j == N - 1:
            return "Yes"

    return "No"

