    min_X_i = L
    max_X_i = R
    for A_i in A:
        if A_i < L:
            min_X_i = L
        elif A_i > R:
            max_X_i = R
        else:
            min_X_i = max(min_X_i, L - A_i)
            max_X_i = min(max_X_i, R + A_i)
