def expected_green_components(grid, H, W):
    green_components = count_green_components(grid, H, W)
    red_cells = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == '.']
    total_red_cells = len(red_cells)

    if total_red_cells == 0:
        return green_components

    expected_value = 0
    for i, j in red_cells:
        # Count the number of green cells in the connected component of (i, j)
        connected_green_cells = 0
        visited = [[False] * W for _ in range(H)]
        bfs(grid, visited, i, j, H, W)
        for x in range(H):
            for y in range(W):
                if grid[x][y] == '#' and not visited[x][y]:
                    connected_green_cells += 1
        # Calculate the expected value
        expected_value += connected_green_cells / total_red_cells
        expected_value %= MOD

    return expected_value

