def floyd_warshall(n, edges):
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v in edges:
        dist[u-1][v-1] = 1
        dist[v-1][u-1] = 1
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

def min_tour_length(n, m, x):
    edges = []
    for i in range(m):
        edges.append((x[i], x[i+1]))
    dist = floyd_warshall(n, edges)
    min_length = float('inf')
    for i in range(n):
        for j in range(n):
            if dist[i][j] > 0:
                min_length = min(min_length, dist[i][j] + 1)
    return min_length

