def find_min_weight_walk(N, M, edges):
    # Initialize distances from vertex 1 to all other vertices as infinity
    distances = [float('inf')] * (N + 1)
    distances[1] = 0

    # Relax edges repeatedly
    for _ in range(N - 1):
        for u, v, w in edges:
            if distances[u] != float('inf') and distances[u] + w < distances[v]:
                distances[v] = distances[u] + w

    # Check if there is a negative cycle
    for u, v, w in edges:
        if distances[u] != float('inf') and distances[u] + w < distances[v]:
            return "No"

    # Check if there is a walk that visits all vertices
    visited = [False] * (N + 1)
    visited[1] = True

    def dfs(v):
        if visited[v]:
            return
        visited[v] = True
        for u, v, w in edges:
            if v == u and distances[v] == distances[u] + w:
                dfs(v)

    dfs(1)

    return distances[N]

