def bfs(grid, start, target):
    queue = deque([(start, 0)])
    visited = set()
    visited.add(start)
    while queue:
        (x, y), moves = queue.popleft()
        if (x, y) == target:
            return moves
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.' and (nx, ny) not in visited:
                queue.append(((nx, ny), moves + 1))
                visited.add((nx, ny))
    return -1

