def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def find_kth_number(N, M, K):
    lcm_NM = lcm(N, M)
    count = K // lcm_NM
    kth_number = lcm_NM * (count + 1)
    return kth_number

