def sieve_of_eratosthenes(max_num):
    is_prime = [True] * (max_num + 1)
    p = 2
    while p * p <= max_num:
        if is_prime[p]:
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1
    prime_factors = {}
    for p in range(2, max_num + 1):
        if is_prime[p]:
            for multiple in range(p, max_num + 1, p):
                prime_factors[multiple] = prime_factors.get(multiple, 0) + 1
    return prime_factors

def count_square_pairs(N, A):
    max_num = max(A)
    prime_factors = sieve_of_eratosthenes(max_num)
    prime_count = {}
    for num in A:
        for prime, count in prime_factors.items():
            if prime in prime_count:
                prime_count[prime] += count
            else:
                prime_count[prime] = count

    count = 0
    for num in A:
        for prime, count in prime_count.items():
            if prime in prime_count and prime_count[prime] > 0:
                count += count * (count - 1) // 2
    return count

