import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
    return distances

def find_latest_arrival_times(N, M, trains):
    graph = {i: {} for i in range(1, N + 1)}
    for l, d, k, c, A, B in trains:
        for t in range(l, l + d, d):
            for i in range(k):
                graph[A][B] = t + c

    latest_arrival_times = {}
    for S in range(1, N):
        distances = dijkstra(graph, S)
        if distances[N] == float('inf'):
            latest_arrival_times[S] = "Unreachable"
        else:
            path = []
            current_node = N
            while current_node != S:
                path.append(current_node)
                current_node = graph[current_node].get(N)
            path.append(S)
            path.reverse()
            latest_arrival_times[S] = max(path)

    return latest_arrival_times

