    A, B = tile
    if x + A > len(grid) or y + B > len(grid[0]):
        return False
    for i in range(A):
        for j in range(B):
            if grid[x + i][y + j] != 0:
                return False
    return True

def place_tile(grid, tile, x, y, tile_id):
    A, B = tile
    for i in range(A):
        for j in range(B):
            grid[x + i][y + j] = tile_id

def remove_tile(grid, tile, x, y):
    A, B = tile
    for i in range(A):
        for j in range(B):
            grid[x + i][y + j] = 0

def backtrack(grid, tiles, tile_id):
    if tile_id == len(tiles):
        return True
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if can_place_tile(grid, tiles[tile_id], i, j):
                place_tile(grid, tiles[tile_id], i, j, tile_id)
                if backtrack(grid, tiles, tile_id + 1):
                    return True
                remove_tile(grid, tiles[tile_id], i, j)
    return False

