from collections import deque

def can_reach_goal(H, W, grid, medicines):
    # Find the start and goal points
    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                goal = (i, j)

    # Create a dictionary to store the energy levels at each cell
    energy_levels = {}
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                energy_levels[(i, j)] = 0
            elif grid[i][j] == 'T':
                energy_levels[(i, j)] = 0
            elif grid[i][j] == '.':
                energy_levels[(i, j)] = 0
            elif grid[i][j] == '#':
                energy_levels[(i, j)] = 0
            else:
                energy_levels[(i, j)] = 0

    # Create a set of medicines
    medicines_set = set(medicines)

    # Create a queue for BFS
    queue = deque([start])

    # Create a set of visited cells
    visited = set([start])

    while queue:
        i, j = queue.popleft()

        # If we reach the goal point, return True
        if (i, j) == goal:
            return True

        # If the energy at the current cell is 0, skip it
        if energy_levels[(i, j)] == 0:
            continue

        # If the current cell is a medicine, set the energy to the medicine's energy
        if (i, j) in medicines_set:
            energy_levels[(i, j)] = medicines[medicines_set.index((i, j))]

        # Explore the adjacent cells
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#' and energy_levels[(ni, nj)] > 0:
                queue.append((ni, nj))
                visited.add((ni, nj))

    # If we exhaust the queue without reaching the goal point, return False
    return False

