def divide_sequence(L, R):
    good_sequences = []
    current_segment = []
    i = 0
    while L < R:
        current_segment.append(L)
        L += 1
        i += 1
        if i == 2:
            current_segment.append(R)
            R += 1
            i = 0
        if L == R:
            break
    return i, good_sequences

