def check_winning_condition(grid):
    # Check rows
    for i in range(3):
        if grid[i][0] == grid[i][1] == grid[i][2]:
            return True
    # Check columns
    for j in range(3):
        if grid[0][j] == grid[1][j] == grid[2][j]:
            return True
    # Check diagonals
    if grid[0][0] == grid[1][1] == grid[2][2]:
        return True
    if grid[0][2] == grid[1][1] == grid[2][0]:
        return True
    return False

def check_remaining_white_cells(grid):
    # Count white cells
    white_cells = 0
    for i in range(3):
        for j in range(3):
            if grid[i][j] == 0:
                white_cells += 1
    return white_cells

def determine_winner(grid):
    total_score = 0
    white_cells = check_remaining_white_cells(grid)

    while white_cells > 0:
        if check_winning_condition(grid):
            return "Takahashi"
        if white_cells == 0:
            return "Takahashi" if total_score > 0 else "Aoki"

        # Takahashi's turn
        best_score = -float('inf')
        best_move = None
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    new_grid = [row[:] for row in grid]
                    new_grid[i][j] = 1
                    new_score = total_score + grid[i][j]
                    if check_winning_condition(new_grid):
                        best_score = max(best_score, new_score)
                        best_move = (i, j)
                    new_grid[i][j] = 0

        # Aoki's turn
        best_score = float('inf')
        best_move = None
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    new_grid = [row[:] for row in grid]
                    new_grid[i][j] = -1
                    new_score = total_score - grid[i][j]
                    if check_winning_condition(new_grid):
                        best_score = min(best_score, new_score)
                        best_move = (i, j)
                    new_grid[i][j] = 0

        if best_move is None:
            return "Takahashi" if total_score > 0 else "Aoki"

        # Update grid and score
        grid[best_move[0]][best_move[1]] = 1
        total_score += grid[best_move[0]][best_move[1]]
        grid[best_move[0]][best_move[1]] = 0

        # Check if the game ends
        if check_winning_condition(grid):
            return "Takahashi" if total_score > 0 else "Aoki"

        # Update white cells
        white_cells = check_remaining_white_cells(grid)

