def can_win(cards, memo):
    if tuple(sorted(cards)) in memo:
        return memo[tuple(sorted(cards))]

    for i in range(len(cards)):
        for j in range(i + 1, len(cards)):
            if cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1]:
                new_cards = cards[:i] + cards[i+1:j] + cards[j+1:]
                if not can_win(new_cards, memo):
                    memo[tuple(sorted(cards))] = True
                    return True

    memo[tuple(sorted(cards))] = False
    return False

