def max_strength(nums, k):
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            current_sum = 0
            for l in range(i, 0, -1):
                current_sum += nums[l - 1]
                dp[i][j] = max(dp[i][j], dp[l - 1][j - 1] + current_sum * (j - 1) - current_sum * (j - 2) + current_sum * (j - 3) - current_sum * (j - 4) + ... + current_sum * 1)

    return dp[n][k]

